const binaryKeys = Object.keys($binary || {});

if (binaryKeys.length > 0) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKeys[0]);
    return [{ json: JSON.parse(buffer.toString('utf-8')) }];
  } catch (e) {
    throw new Error(`Binary read failed (key=${binaryKeys[0]}): ${e.message}`);
  }
}

if ($json.body) {
  const raw = $json.body;
  try {
    return [{ json: typeof raw === 'string' ? JSON.parse(raw) : raw }];
  } catch (e) {
    throw new Error(`Body parse failed (type=${typeof raw}): ${e.message}`);
  }
}

throw new Error(`No data. $json keys: [${Object.keys($json||{}).join(',')}], $binary keys: [${Object.keys($binary||{}).join(',')}]`);

const payload = $('Parse Body').item.json;
const formResp = $('Get Form Details').item.json;
const submissionsResp = $json;

const formData = formResp?.ocs?.data;
const submissionsData = submissionsResp?.ocs?.data;

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
function escMultiline(s) {
  return esc(s).replace(/\n/g, '<br>');
}

// Build a human-readable diagnostic block for any failed HTTP response.
// Surfaces the actual status code + message instead of swallowing it.
function diagnose(label, resp, url) {
  if (resp && resp.error) {
    const e = resp.error;
    return {
      ok: false,
      html: `<p style="color:#b00;"><strong>${esc(label)} failed.</strong><br>` +
            `URL: <code>${esc(url)}</code><br>` +
            `Message: ${esc(e.message || 'Unknown error')}<br>` +
            (e.description ? `Detail: ${esc(e.description)}<br>` : '') +
            (e.httpCode ? `HTTP: ${esc(e.httpCode)}` : '') +
            `</p>`,
      summary: `${label} failed: ${e.description || e.message || 'unknown'}`,
    };
  }
  if (resp && resp.ocs?.meta && resp.ocs.meta.statuscode && resp.ocs.meta.statuscode >= 300) {
    return {
      ok: false,
      html: `<p style="color:#b00;"><strong>${esc(label)} returned OCS error.</strong><br>` +
            `URL: <code>${esc(url)}</code><br>` +
            `OCS status: ${esc(resp.ocs.meta.statuscode)} ${esc(resp.ocs.meta.message || '')}` +
            `</p>`,
      summary: `${label} OCS ${resp.ocs.meta.statuscode}: ${resp.ocs.meta.message || ''}`,
    };
  }
  if (!resp || resp.ocs?.data === undefined) {
    return {
      ok: false,
      html: `<p style="color:#b00;"><strong>${esc(label)} returned unexpected payload.</strong><br>` +
            `URL: <code>${esc(url)}</code><br>` +
            `Raw (truncated): <code>${esc(JSON.stringify(resp).slice(0, 400))}</code></p>`,
      summary: `${label} unexpected payload`,
    };
  }
  return { ok: true };
}

const formId = payload.event.form.id;
const formUrl = `https://nextcloud.example.org/ocs/v2.php/apps/forms/api/v3/forms/${formId}`;
const submissionsUrl = `https://nextcloud.example.org/ocs/v2.php/apps/forms/api/v3/forms/${formId}/submissions`;

const formDiag = diagnose('Get Form Details', formResp, formUrl);
const submissionsDiag = diagnose('Get Form Submissions', submissionsResp, submissionsUrl);

// Build answers HTML or fall back to a clear error block.
let answersHtml = '';
if (submissionsDiag.ok) {
  const targetSubmissionId = payload.event.submission.id;
  const submission = (submissionsData.submissions || []).find(s => s.id === targetSubmissionId);
  const questions = submissionsData.questions || [];

  if (submission && questions.length) {
    const byQ = {};
    for (const a of (submission.answers || [])) {
      if (!byQ[a.questionId]) byQ[a.questionId] = [];
      byQ[a.questionId].push(a.text);
    }
    const rows = questions.map(q => {
      const vals = byQ[q.id] || [];
      const answer = vals.length
        ? vals.map(v => escMultiline(v)).join(', ')
        : '<em style="color:#888;">(no answer)</em>';
      return `<tr><td style="padding:6px 12px 6px 0;vertical-align:top;font-weight:bold;">${esc(q.text)}</td><td style="padding:6px 0;vertical-align:top;">${answer}</td></tr>`;
    }).join('');
    answersHtml = `<h3 style="margin:18px 0 6px;">Submitted answers</h3><table style="border-collapse:collapse;font-family:sans-serif;">${rows}</table>`;
  } else {
    answersHtml = `<p style="color:#b00;"><strong>Submission #${esc(targetSubmissionId)} not found in API response.</strong><br>` +
      `Found ${esc((submissionsData.submissions || []).length)} submissions, ${esc(questions.length)} questions on form ${esc(formId)}.</p>`;
  }
} else {
  answersHtml = submissionsDiag.html;
}

// If form details failed, fall back to webhook data and notify owner only.
// Prepend the form-details diagnostic so we don't lose that error either.
if (!formDiag.ok) {
  const form = payload.event.form;
  return [{
    json: {
      shareType: 'user',
      shareWith: form.ownerId,
      displayName: form.ownerId,
      formId: form.id,
      formHash: form.hash,
      formTitle: form.title || '(Untitled Form)',
      submittedBy: payload.user.displayName || 'Anonymous',
      submittedByUid: payload.user.uid,
      submissionId: payload.event.submission.id,
      submissionTimestamp: payload.event.submission.timestamp,
      answersHtml: formDiag.html + answersHtml,
    }
  }];
}

const form = formData;
const notifyList = [];
const submittedBy = payload.user.displayName || 'Anonymous';

const baseContext = {
  formId: form.id,
  formHash: form.hash,
  formTitle: form.title,
  submittedBy,
  submittedByUid: payload.user.uid,
  submissionId: payload.event.submission.id,
  submissionTimestamp: payload.event.submission.timestamp,
  answersHtml,
};

notifyList.push({
  shareType: 'user',
  shareWith: form.ownerId,
  displayName: form.ownerId,
  ...baseContext,
});

for (const share of (form.shares || [])) {
  const canViewResults = Array.isArray(share.permissions)
    ? share.permissions.includes('results')
    : false;
  if (!canViewResults) continue;
  if (share.shareType === 0 && share.shareWith === form.ownerId) continue;

  notifyList.push({
    shareType: share.shareType === 1 ? 'group' : 'user',
    shareWith: share.shareWith,
    displayName: share.displayName || share.shareWith,
    ...baseContext,
  });
}

const seen = new Set();
return notifyList
  .filter(s => {
    const key = `${s.shareType}:${s.shareWith}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .map(item => ({ json: item }));

const members = $json.ocs?.data?.users || [];
const context = $('Is Group Share?').item.json;

if (members.length === 0) return [];

return members.map(userId => ({
  json: {
    userId,
    formId: context.formId,
    formHash: context.formHash,
    formTitle: context.formTitle,
    submittedBy: context.submittedBy,
    submittedByUid: context.submittedByUid,
    submissionId: context.submissionId,
    submissionTimestamp: context.submissionTimestamp,
    answersHtml: context.answersHtml,
  }
}));
